/*
 * The "קווים עדינים" background (ENG-72): loose looping lines of one width
 * with round caps, as on the approved mockup, laid out on a large seamless
 * tile so they cover any viewport (the tile repeats; a phone sees part of one).
 *
 * The tile is generated by a seeded random walk on a torus: each line wanders
 * with a slowly changing curvature and now and then curls into a loop, and
 * stops before it comes near another line, so the page stays calm and even.
 * Lines that cross the tile's edge are drawn again on the other side, which
 * makes the tile seamless.
 *
 * Generation runs once, in `scripts/gen-background-tile.mjs` via
 * `generateLinesTile`, and the result is committed in lines-tile.data.ts:
 * Math.sin / cos may differ in the last bit between JavaScript engines, and
 * the server and the browser must draw exactly the same paths.
 */

export const TILE_WIDTH = 1200
export const TILE_HEIGHT = 960
/** Stroke width of the lines, in CSS px */
export const LINE_WIDTH = 18

export interface TilePath {
  /** SVG path data, in tile coordinates (may run past the tile's edge) */
  d: string
  /** Which palette colour: 0 the first (indigo), 1 the second (pink) */
  color: 0 | 1
  /** Offsets the path is also drawn at (multiples of the tile size), so the tile is seamless */
  copies: ReadonlyArray<readonly [number, number]>
}

export interface Point {
  x: number
  y: number
}

/** Small seeded PRNG (mulberry32): the same tile on every run. */
export function seededRandom(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** Shortest signed difference on a ring of length `period`. */
export function wrapDelta(d: number, period: number): number {
  return d - period * Math.round(d / period)
}

/** Distance between two points on the torus (the tile repeats both ways). */
export function torusDistance(a: Point, b: Point, w = TILE_WIDTH, h = TILE_HEIGHT): number {
  return Math.hypot(wrapDelta(a.x - b.x, w), wrapDelta(a.y - b.y, h))
}

/** Smooth path through points: Catmull-Rom turned into cubic Béziers. */
export function smoothPath(points: Point[], digits = 1): string {
  const f = (n: number) => Number(n.toFixed(digits)).toString()
  if (points.length < 2) return ''
  let d = `M${f(points[0].x)} ${f(points[0].y)}`
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[Math.max(0, i - 1)]
    const p1 = points[i]
    const p2 = points[i + 1]
    const p3 = points[Math.min(points.length - 1, i + 2)]
    const c1 = { x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6 }
    const c2 = { x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6 }
    d += `C${f(c1.x)} ${f(c1.y)} ${f(c2.x)} ${f(c2.y)} ${f(p2.x)} ${f(p2.y)}`
  }
  return d
}

/**
 * Offsets (multiples of the tile) at which a path with this bounding box
 * must also be drawn so the tile is seamless: every copy that reaches into
 * the tile, the original (0, 0) included.
 */
export function tileCopies(
  box: { minX: number; minY: number; maxX: number; maxY: number },
  w = TILE_WIDTH,
  h = TILE_HEIGHT,
  pad = LINE_WIDTH
): Array<[number, number]> {
  const out: Array<[number, number]> = []
  for (let i = -2; i <= 2; i++) {
    for (let j = -2; j <= 2; j++) {
      const dx = i * w
      const dy = j * h
      if (box.maxX + dx + pad < 0 || box.minX + dx - pad > w) continue
      if (box.maxY + dy + pad < 0 || box.minY + dy - pad > h) continue
      out.push([dx, dy])
    }
  }
  return out
}

/** Points of a spatial hash on the torus, for "is another line near here?" */
class TorusHash {
  private cells = new Map<string, Array<{ p: Point; line: number }>>()
  private cell: number
  private w: number
  private h: number
  constructor(cell: number, w: number, h: number) {
    this.cell = cell
    this.w = w
    this.h = h
  }
  private key(cx: number, cy: number) {
    const nx = Math.ceil(this.w / this.cell)
    const ny = Math.ceil(this.h / this.cell)
    return `${((cx % nx) + nx) % nx},${((cy % ny) + ny) % ny}`
  }
  add(p: Point, line: number) {
    const k = this.key(Math.floor(p.x / this.cell), Math.floor(p.y / this.cell))
    const list = this.cells.get(k)
    if (list) list.push({ p, line })
    else this.cells.set(k, [{ p, line }])
  }
  /** Distance to the nearest point of another line, up to `limit` (else Infinity). */
  nearestOther(p: Point, line: number, limit: number): number {
    const cx = Math.floor(p.x / this.cell)
    const cy = Math.floor(p.y / this.cell)
    const r = Math.ceil(limit / this.cell)
    let best = Infinity
    for (let i = -r; i <= r; i++) {
      for (let j = -r; j <= r; j++) {
        const list = this.cells.get(this.key(cx + i, cy + j))
        if (!list) continue
        for (const q of list) {
          if (q.line === line) continue
          const dist = torusDistance(p, q.p, this.w, this.h)
          if (dist < best) best = dist
        }
      }
    }
    return best <= limit ? best : Infinity
  }
}

export interface TileOptions {
  seed?: number
  width?: number
  height?: number
  /** Total length of line to lay down, in px per 100,000 px² of tile */
  density?: number
  /** Minimum distance between the centres of two different lines */
  clearance?: number
}

/**
 * Lays out the tile. Deterministic for a seed (on one JavaScript engine).
 * Returns the paths and the raw centre-line points (for tests).
 */
export function generateLinesTile(opts: TileOptions = {}): { paths: TilePath[]; lines: Point[][] } {
  const w = opts.width ?? TILE_WIDTH
  const h = opts.height ?? TILE_HEIGHT
  const rand = seededRandom(opts.seed ?? 72)
  const clearance = opts.clearance ?? 54
  const targetLength = ((opts.density ?? 1000) * w * h) / 100_000
  const hash = new TorusHash(32, w, h)
  const step = 4
  const lines: Point[][] = []
  const colors: Array<0 | 1> = []
  let total = 0
  let attempts = 0

  while (total < targetLength && attempts < 600) {
    attempts++
    const id = lines.length
    // Start where the page is emptiest: the best of a few random candidates
    let start: Point = { x: rand() * w, y: rand() * h }
    let bestScore = -1
    for (let k = 0; k < 28; k++) {
      const c = { x: rand() * w, y: rand() * h }
      const near = hash.nearestOther(c, id, 260)
      const score = near === Infinity ? 260 : near
      if (score > bestScore) {
        bestScore = score
        start = c
      }
    }
    if (bestScore < clearance * 1.4) continue

    let theta = rand() * Math.PI * 2
    let k = 0
    let sign = rand() < 0.5 ? -1 : 1
    let target = sign / (90 + rand() * 120)
    let untilChange = 90 + rand() * 160
    let loopLeft = 0
    let loopTotal = 1
    let loopR = 60
    const length = 700 + rand() * 700
    const pts: Point[] = [start]
    let p = start
    let travelled = 0
    let loops = 0
    let stuck = false
    while (travelled < length && !stuck) {
      if (loopLeft > 0) {
        loopLeft -= step
        // A curl tightens and opens again (a teardrop, not a circle)
        const t = 1 - loopLeft / loopTotal
        target = (sign / loopR) * (0.45 + 0.85 * Math.sin(Math.PI * t))
        if (loopLeft <= 0) {
          sign = -sign
          target = sign / (110 + rand() * 120)
        }
      } else if ((untilChange -= step) <= 0) {
        // Bends swing one way, then the other (loose S-curves); now and then
        // one keeps turning into a wide, open loop
        sign = -sign
        if (loops < 1 && rand() < 0.4) {
          loopR = 40 + rand() * 30
          loopTotal = loopLeft = 2 * Math.PI * loopR * (1.05 + rand() * 0.25)
          loops++
        } else {
          target = sign / (70 + rand() * 130)
        }
        untilChange = 110 + rand() * 170
      }
      // Curvature eases toward its target, so bends start and end softly
      k += (target - k) * (loopLeft > 0 ? 0.08 : 0.05)
      theta += k * step
      // Near another line: bend away a little at a time; stop if no way through
      let next: Point | null = null
      for (const turn of [0, 0.04, -0.04, 0.08, -0.08]) {
        const t = theta + turn
        const cand = { x: p.x + Math.cos(t) * step, y: p.y + Math.sin(t) * step }
        if (hash.nearestOther(cand, id, clearance) === Infinity) {
          next = cand
          theta = t
          break
        }
      }
      if (!next) {
        stuck = true
        break
      }
      pts.push(next)
      p = next
      travelled += step
    }
    if (travelled < 320) continue
    for (const q of pts) hash.add(q, id)
    // The opposite colour of the nearest line, so neither colour clumps
    let nearest = -1
    let nearestDist = Infinity
    for (let i = 0; i < lines.length; i++) {
      for (let j = 0; j < lines[i].length; j += 6) {
        for (let m = 0; m < pts.length; m += 6) {
          const dist = torusDistance(pts[m], lines[i][j], w, h)
          if (dist < nearestDist) { nearestDist = dist; nearest = i }
        }
      }
    }
    colors.push(nearest < 0 ? 0 : ((1 - colors[nearest]) as 0 | 1))
    lines.push(pts)
    total += travelled
  }

  const paths: TilePath[] = lines.map((pts, i) => {
    const sampled = pts.filter((_, j) => j % 5 === 0 || j === pts.length - 1)
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
    for (const q of sampled) {
      minX = Math.min(minX, q.x); maxX = Math.max(maxX, q.x)
      minY = Math.min(minY, q.y); maxY = Math.max(maxY, q.y)
    }
    return {
      d: smoothPath(sampled),
      color: colors[i],
      copies: tileCopies({ minX, minY, maxX, maxY }, w, h),
    }
  })
  return { paths, lines }
}
